	m.profile(indicator(goal)).Tries++
	head, body := copyClause(clause)
	if !m.Bindings.unify(head, goal) {
		return false
	}
	m.Goals = continuation
	if body != nil {
		m.Goals = prepend([]GoalEntry{goalEntry(body, barrier, context)}, continuation)
